/**
 * @file weather_watch.gen.h
 * @brief GENERATED by scripts/vars_gen.py from weather_watch.toml
 */

#ifndef SITE_PROGRAM_WEATHER_WATCH_GEN_H
#define SITE_PROGRAM_WEATHER_WATCH_GEN_H

#include <cstdint>

#include "libbotanik.h"

#include "../../../vars.h"

namespace Site {

using namespace Botanik;

/**
 * @brief The weather station, watched: whether it is answering, and whether what
 *        it says is a storm.
 */
class WeatherWatch final : public Plc::Program {

public:

    /** @name VAR_INPUT
     *  @{ */

    Vars::RefIn<float> wind;
    Vars::RefIn<float> gust;
    Vars::RefIn<float> rain;
    Vars::RefIn<float> irrad;
    Vars::RefIn<bool>  rain_lock;
    Vars::RefIn<bool>  wind_lock;

    /** @} */

    /** @name VAR_OUTPUT
     *  @{ */

    Vars::RefOut<bool>     station;
    Vars::RefOut<bool>     storm;
    Vars::RefOut<uint16_t> since_rain;

    /** @} */

private:

    /** @name VAR - what this law remembers
     *  @{ */

    /** @brief Whether the station has EVER answered. Before it has, silence
     *  is bring-up; after, it is a fault. @see AcSupply */
    bool     _seen = false;
    /** @brief Ms since the gauge last read wet, and whether it ever has in
     *  this run. A boot does not know when it last rained, so before the
     *  first shower the row is held rather than reading "just now". */
    uint64_t _dry_ms = 0;
    bool     _wet_seen = false;

    /** @} */

    Vars::VarRef _watch_rows[6];  ///< swept for validity before each activation

public:
    WeatherWatch(const SetupContext& ctx, Vars::Bank& io)
        : Program(ctx, "weather_watch", Tasks::GROUP_SLOW, io) {}

protected:
    /** @brief Resolve every name. An output is CLAIMED here. */
    void bind(Vars::Bank& io) override;
    void run(ProgramContext& c) override;
    void observe(ProgramContext& c) override;  ///< reports in EVERY state
};

inline void WeatherWatch::bind(Vars::Bank& io) {
    wind       = io.resolve_in<float>("cli_wind_mps");
    gust       = io.resolve_in<float>("cli_windGust_mps");
    rain       = io.resolve_in<float>("cli_rain_mmph");
    irrad      = io.resolve_in<float>("cli_irrad_Wpm2");
    rain_lock  = io.resolve_in<bool>("cli_rainLockout");
    wind_lock  = io.resolve_in<bool>("cli_windLockout");
    station    = io.resolve_out<bool>("alarm_wx_station");
    storm      = io.resolve_out<bool>("alarm_weather_storm");
    since_rain = io.resolve_out<uint16_t>("cli_sinceRain_min");

    // What the base sweeps before each activation, so an input that has
    // stopped being believable is DEGRADED without the law asking.
    _watch_rows[0] = wind.r;
    _watch_rows[1] = gust.r;
    _watch_rows[2] = rain.r;
    _watch_rows[3] = irrad.r;
    _watch_rows[4] = rain_lock.r;
    _watch_rows[5] = wind_lock.r;
    set_inputs(_watch_rows, 6);
    set_health_row(io.resolve_out<uint8_t>("prog_weather_watch"));
}

}  // namespace Site

#endif // SITE_PROGRAM_WEATHER_WATCH_GEN_H
